  "Encerrar treino": ["End workout", "Terminar entreno", "结束训练", "वर्कआउट ख़त्म करो", "Terminer la séance"],
  "série {n}": ["set {n}", "serie {n}", "第 {n} 组", "सेट {n}", "série {n}"],
